INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l31',3,7,31,'A Lovable Eccentric','可爱的怪人','介词 + 动名词(without/instead of/interested in doing)、分词短语作状语(preferring / recognizing)、pay attention to·care about·take care of、间接疑问句的语序(不倒装)、mind·insist on·imagine + 物主代词 + 动名词(原创承载 NCE3 L31 考点·无需净化:富有怪人迪基淋雨后衣衫不整走进名店,店员拒绝招待,他用三万枚硬币付账,又花四年伪造现代画展愚弄评论家·温情喜剧)','真正的怪人从不刻意引人注目。他们无视社会习俗,却意识不到自己在做什么出格的事。这几乎总能赢得别人的喜爱与尊敬,因为他们给平淡的日常生活添了几分色彩。直到去世前,理查德·科尔森一直是我们镇上最引人注目的人物之一。他是个精明而富有的生意人,可镇上大多数人几乎不了解他的这一面。在我们所有人眼里,他就是迪基,他的古怪早在去世前很久就成了传奇。迪基极其讨厌势利眼。他虽然有一辆大轿车,却几乎从不用,总爱步行。哪怕下着倾盆大雨,他也拒绝带伞。有一天,他淋了一场大雨之后,走进一家名贵的店,想给妻子买一块三百美元的手表。可他浑身湿淋淋、一副狼狈相,店员竟拒绝招待他。迪基二话不说走了,又拎着一个大布袋回来。布袋沉甸甸的,他把它往柜台上一放。店员请他离开,迪基却毫不理会,要求见经理。经理认出这位顾客是谁后,连声道歉,把店员狠狠训斥了一顿。等迪基拿到手表,他把那个布袋递给店员——里面装着三百美元的硬币,总共三万枚!他坚持要店员在他离开前把每一枚都点清。还有一次,他邀请了一批重要的评论家来看他私人收藏的现代画。这场画展在报界引起了很大关注,因为那些画本以为是名家之作,其实全都出自迪基本人之手。他花了整整四年,精心策划这个玩笑,只为证明评论家并不总是懂他们所谈的东西。','{"q":"Listen and answer — Why did the clerk at first refuse to serve Dickie?","options":["Because Dickie looked wet and bedraggled","Because the store was closed","Because Dickie was rude","Because Dickie had no money"],"answer_index":0}'::jsonb,'{"title":"介词+动名词 / 分词短语 / pay attention to / 间接疑问句语序 / insist on his doing","intro":"①介词后接动名词:without being / instead of using / interested in collecting。②分词短语作状语,表原因或时间:Preferring to walk, he…；Recognizing who it was, he…。③pay attention to(注意)、care about(在乎)、take care of(照顾)。④间接疑问句用陈述句的正常语序(不倒装、不用 do):knew who the customer was;asked if it was expensive。⑤mind / insist on / imagine + 物主代词 + 动名词:mind my opening;insist on the clerk''s counting。","table":{"headers":["用法","意思","例子"],"rows":[["介词 + 动名词","without / instead of + -ing","without being conscious"],["分词短语作状语","表原因/时间","Recognizing who it was, he…"],["pay attention to / take care of","注意 / 照顾","paid no attention to him"],["间接疑问句语序 / insist on his doing","不倒装 / 物主+动名词","knew who the customer was"]]},"specialRules":[{"rule":"间接疑问句(嵌在句子里的问句)要用陈述句的正常语序,不倒装、不加 do:knew who the customer was(不是 who was the customer)。","mark":"embedded question"},{"rule":"mind / insist on / imagine 后面的动名词,前面的人用物主代词:mind my opening the window;insist on the clerk''s counting。","mark":"物主代词 + 动名词"},{"rule":"美式:store(英式 shop)、clerk(英式 shop assistant)、color(英式 colour)、dollar(英式 pound)。本课已按美语写。","mark":"store / clerk / color"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l31',1,NULL,'True eccentrics never deliberately set out to draw attention to themselves. They disregard social conventions without being conscious that they are doing anything out of the ordinary. This invariably wins them the affection and respect of others, for they add color to the dull routine of everyday life.','真正的怪人从不刻意引人注目。他们无视社会习俗,却意识不到自己在做什么出格的事。这几乎总能赢得别人的喜爱与尊敬,因为他们给平淡的日常生活添了几分色彩。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l31',2,NULL,'Up to the time of his death, Richard Colson was one of the most notable figures in our town. He was a shrewd and wealthy businessman, but most people hardly knew anything about that side of his life. To all of us he was simply Dickie, and his eccentricity had become legendary long before he died.','直到去世前,理查德·科尔森一直是我们镇上最引人注目的人物之一。他是个精明而富有的生意人,可镇上大多数人几乎不了解他的这一面。在我们所有人眼里,他就是迪基,他的古怪早在去世前很久就成了传奇。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l31',3,NULL,'Dickie disliked snobs intensely. Though he owned a large car, he hardly ever used it, preferring always to go on foot. Even when it was pouring, he refused to carry an umbrella. One day, after being caught in a heavy shower, he walked into an expensive store to buy a $300 watch for his wife. He was in such a bedraggled condition that a clerk refused to serve him.','迪基极其讨厌势利眼。他虽然有一辆大轿车,却几乎从不用,总爱步行。哪怕下着倾盆大雨,他也拒绝带伞。有一天,他淋了一场大雨之后,走进一家名贵的店,想给妻子买一块三百美元的手表。可他浑身湿淋淋、一副狼狈相,店员竟拒绝招待他。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l31',4,NULL,'Dickie left without a word and came back carrying a large cloth bag. Since it was extremely heavy, he dumped it on the counter. The clerk asked him to leave, but Dickie paid no attention and asked to see the manager. Recognizing who the customer was, the manager was most apologetic and reprimanded the clerk severely.','迪基二话不说走了,又拎着一个大布袋回来。布袋沉甸甸的,他把它往柜台上一放。店员请他离开,迪基却毫不理会,要求见经理。经理认出这位顾客是谁后,连声道歉,把店员狠狠训斥了一顿。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l31',5,NULL,'When Dickie was handed the watch, he presented the clerk with the cloth bag. It contained $300 in pennies, thirty thousand pennies in all! He insisted on the clerk''s counting every coin before he left. On another occasion, he invited a number of important critics to view his private collection of modern paintings, for though the pictures were supposed to be the work of famous artists, they had in fact all been painted by Dickie himself. It had taken him four years to stage this elaborate joke, simply to prove that critics do not always know what they are talking about.','等迪基拿到手表,他把那个布袋递给店员——里面装着三百美元的硬币,总共三万枚!他坚持要店员在他离开前把每一枚都点清。还有一次,他邀请了一批重要的评论家来看他私人收藏的现代画,因为那些画本以为是名家之作,其实全都出自迪基本人之手。他花了整整四年,精心策划这个玩笑,只为证明评论家并不总是懂他们所谈的东西。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
