INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l31','pay attention to','',NULL,'/peɪ əˈtenʃən tə/','Dickie paid no attention to the clerk.','迪基没理会那个店员。','Please pay attention to the road.','请注意路况。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l31','on foot','',NULL,'/ɑːn fʊt/','He preferred to go on foot.','他宁愿步行。','We came here on foot.','我们是走着来的。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l31','draw attention to','',NULL,'/drɔː əˈtenʃən tə/','True eccentrics never draw attention to themselves.','真正的怪人从不刻意引人注目。','Don''t draw attention to your mistakes.','别把注意力引到你的错误上。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l31','in all','',NULL,'/ɪn ɔːl/','Thirty thousand pennies in all!','总共三万枚硬币!','There were fifty guests in all.','客人总共有五十位。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',5,'am3_l31_gp1','choice','{"stem":"\"They disregard conventions without ___ conscious of it.\"(介词 without 后接动名词 -ing)","options":["be","being","to be","been"],"answer_index":1,"stem_cn":"他们打破习俗却意识不到。","explanation_cn":"介词 without 后面接动名词 -ing。✓ without being conscious of it. ✗ be / to be / been:介词后用动名词 being。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',5,'am3_l31_gp1','choice','{"stem":"\"Instead of ___ the car, he preferred to walk.\"(介词 instead of 后接 -ing)","options":["use","to use","used","using"],"answer_index":3,"stem_cn":"他不开车,宁愿走路。","explanation_cn":"介词 instead of 后面接动名词 -ing。✓ Instead of using the car… ✗ use / to use / used:介词后用 -ing。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',5,'am3_l31_gp1','choice','{"stem":"\"He was interested in ___ modern paintings.\"(介词 in 后接 -ing)","options":["collect","collecting","collected","to collect"],"answer_index":1,"stem_cn":"他热衷于收藏现代画。","explanation_cn":"介词 in 后面接动名词 -ing;be interested in doing。✓ interested in collecting paintings. ✗ collect / to collect / collected:介词后用 -ing。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',5,'am3_l31_gp2','choice','{"stem":"\"___ always to go on foot, he rarely used his car.\"(用分词短语表\"因为偏爱…\")","options":["Preferring","He preferred","Prefer","Preferred to"],"answer_index":0,"stem_cn":"因为总爱步行,他很少开车。","explanation_cn":"用现在分词短语作状语,表原因“因为偏爱…”。✓ Preferring always to go on foot, he… ✗ Prefer / Preferred to / He preferred:此处用分词 Preferring。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',5,'am3_l31_gp2','choice','{"stem":"\"___ who the customer was, the manager apologized.\"(用分词短语表\"认出…后\")","options":["Recognize","He recognized","Recognizing","Recognized by"],"answer_index":2,"stem_cn":"认出顾客是谁后,经理连忙道歉。","explanation_cn":"用现在分词短语作状语,表时间“认出…后”。✓ Recognizing who the customer was, the manager… ✗ Recognize / He recognized / Recognized by:用分词 Recognizing。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',5,'am3_l31_gp2','choice','{"stem":"\"___ caught in a heavy shower, he walked into a store.\"(表\"被…之后\",用分词的完成被动形式)","options":["After be","After been","For being","After being"],"answer_index":3,"stem_cn":"淋了一场大雨之后,他走进一家店。","explanation_cn":"表“被…之后”,用 After being + 过去分词(分词的完成被动)。✓ After being caught in a shower, he… ✗ After be / After been / For being:固定用 After being + 过去分词。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',5,'am3_l31_gp3','choice','{"stem":"\"Dickie paid no ___ to the clerk and asked for the manager.\"(pay ___ to sb,\"注意\")","options":["respect","attention","price","care"],"answer_index":1,"stem_cn":"迪基没理会店员,要见经理。","explanation_cn":"“注意、理会”用 pay attention to sb。✓ paid no attention to the clerk. ✗ care / respect / price:pay 搭配 attention。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',5,'am3_l31_gp3','choice','{"stem":"\"Please take ___ of yourself when you travel.\"(take ___ of sb,\"照顾\")","options":["care","attention","notice","part"],"answer_index":0,"stem_cn":"旅行时请照顾好自己。","explanation_cn":"“照顾”用 take care of sb。✓ take care of yourself. ✗ attention / notice / part:take 搭配 care of。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',5,'am3_l31_gp3','choice','{"stem":"\"He doesn''t ___ about what snobs think of him.\"(\"在乎、介意\"用哪个动词)","options":["attend","take","care","pay"],"answer_index":2,"stem_cn":"他不在乎势利者怎么看他。","explanation_cn":"“在乎、介意”用动词 care about。✓ doesn''t care about what snobs think. ✗ pay / take / attend:表“在乎”用 care。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',5,'am3_l31_gp4','choice','{"stem":"\"The manager knew ___.\"(间接疑问,用陈述句的正常语序)","options":["who the customer was","was who the customer","who the customer is he","who was the customer"],"answer_index":0,"stem_cn":"经理知道这位顾客是谁。","explanation_cn":"间接疑问句用陈述句的正常语序(不倒装)。✓ knew who the customer was. ✗ who was the customer(倒装了)/ who the customer is he / was who the customer:间接疑问不倒装。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',5,'am3_l31_gp4','choice','{"stem":"\"I don''t know ___.\"(间接疑问,不倒装、不加 do)","options":["why did he do it","why he did do it","why he did it","did why he do it"],"answer_index":2,"stem_cn":"我不知道他为什么这么做。","explanation_cn":"间接疑问句不倒装、不加 do。✓ don''t know why he did it. ✗ why did he do it(倒装+do)/ why he did do it / did why he do it:间接疑问用正常语序。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',5,'am3_l31_gp4','choice','{"stem":"\"She asked ___.\"(间接的一般疑问,语序不倒装)","options":["if was the watch expensive","the watch if expensive","was the watch expensive","if the watch was expensive"],"answer_index":3,"stem_cn":"她问那块表贵不贵。","explanation_cn":"间接的一般疑问用 if 引导,后面用陈述句语序。✓ asked if the watch was expensive. ✗ was the watch expensive(倒装)/ if was the watch expensive / the watch if expensive:if 后不倒装。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',5,'am3_l31_gp5','choice','{"stem":"\"He insisted on ___ counting the money.\"(insist on + 物主代词 + 动名词)","options":["that the clerk","the clerk''s","the clerk to","to the clerk"],"answer_index":1,"stem_cn":"他坚持要店员点清钱数。","explanation_cn":"insist on 后接动名词,做这动作的人用物主代词(名词加''s)。✓ insisted on the clerk''s counting. ✗ the clerk to / to the clerk / that the clerk:用 the clerk''s + 动名词。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',5,'am3_l31_gp5','choice','{"stem":"\"Would you mind ___ opening the window?\"(mind + 物主代词 + 动名词)","options":["that I","I","me to","my"],"answer_index":3,"stem_cn":"你介意我开下窗吗?","explanation_cn":"mind 后接动名词,做这动作的人用物主代词 my。✓ Would you mind my opening…? ✗ I / me to / that I:用 my + 动名词。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',5,'am3_l31_gp5','choice','{"stem":"\"Imagine ___ paying for a watch with 30,000 pennies!\"(imagine + 物主代词 + 动名词)","options":["his","him to","he","that he"],"answer_index":0,"stem_cn":"想象一下他用三万枚硬币买表!","explanation_cn":"imagine 后接动名词,做这动作的人用物主代词 his。✓ Imagine his paying with 30,000 pennies! ✗ he / him to / that he:用 his + 动名词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',5,'am3_l31_gp6','choice','{"stem":"\"A person who behaves in an odd but harmless way is ___.\"(\"古怪的人\"用哪个词)","options":["polite","ordinary","famous","eccentric"],"answer_index":3,"stem_cn":"行为古怪却无害的人。","explanation_cn":"行为古怪却无害的人是 eccentric。✓ true eccentrics. ✗ ordinary 普通;✗ famous 出名;✗ polite 礼貌——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',5,'am3_l31_gp6','choice','{"stem":"\"A sharp, clever businessman is ___.\"(\"精明的\"用哪个词)","options":["shrewd","lazy","shy","weak"],"answer_index":0,"stem_cn":"精明的生意人。","explanation_cn":"精明、机敏的是 shrewd。✓ a shrewd businessman. ✗ lazy 懒;✗ shy 害羞;✗ weak 弱——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',5,'am3_l31_gp6','choice','{"stem":"\"To scold someone officially for a fault is to ___ them.\"(\"训斥、斥责\"用哪个词)","options":["thank","praise","reprimand","invite"],"answer_index":2,"stem_cn":"因过错正式责备某人。","explanation_cn":"因过错正式责备某人是 reprimand(训斥)。✓ reprimanded the clerk. ✗ praise 表扬;✗ thank 感谢;✗ invite 邀请——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',6,NULL,'choice','{"stem":"lovable 的意思是:","options":["可爱的","可怕的","危险的","无聊的"],"answer_index":0,"explanation_cn":"lovable = 可爱的。✓ a lovable eccentric 可爱的怪人。\n顺带记:可怕的 = terrible;无聊的 = boring;危险的 = dangerous."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',6,NULL,'choice','{"stem":"eccentric 的意思是:","options":["勤奋的","礼貌的","(行为)古怪的","普通的"],"answer_index":2,"explanation_cn":"eccentric = (行为)古怪的。✓ true eccentrics 真正的怪人。\n顺带记:普通的 = ordinary;礼貌的 = polite;勤奋的 = diligent."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',6,NULL,'choice','{"stem":"disregard 的意思是:","options":["不顾,漠视","喜爱","遵守","记住"],"answer_index":0,"explanation_cn":"disregard = 不顾、漠视。✓ disregard social conventions 无视社会习俗。\n顺带记:遵守 = obey;喜爱 = love;记住 = remember."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',6,NULL,'choice','{"stem":"shrewd 的意思是:","options":["懒惰的","害羞的","愚蠢的","精明的"],"answer_index":3,"explanation_cn":"shrewd = 精明的。✓ a shrewd businessman 精明的生意人。\n顺带记:愚蠢的 = foolish;害羞的 = shy;懒惰的 = lazy."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',6,NULL,'choice','{"stem":"legendary 的意思是:","options":["真实的","普通的","传奇般的","短暂的"],"answer_index":2,"explanation_cn":"legendary = 传奇般的。✓ his eccentricity was legendary 他的古怪成了传奇。\n顺带记:短暂的 = brief;真实的 = real;普通的 = common."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',6,NULL,'choice','{"stem":"bedraggled 的意思是:","options":["湿淋淋、狼狈的","干燥的","崭新的","整洁的"],"answer_index":0,"explanation_cn":"bedraggled = 湿淋淋、狼狈的。✓ in a bedraggled condition 一副狼狈相。\n顺带记:整洁的 = neat;崭新的 = brand-new;干燥的 = dry."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',7,NULL,'cloze','{"stem":"第 1 空","context":"True eccentrics disregard social conventions without ___1___ conscious of it. Dickie, a shrewd businessman, was caught in the rain and walked ___2___ an expensive store. A clerk refused to serve him, but Dickie paid no ___3___ and asked for the manager. He later paid for the watch with 30,000 pennies ___4___ all.","blank_no":1,"options":["being","be","to be","been"],"answer_index":0,"explanation_cn":"介词 without 后接动名词 -ing。✓ disregard conventions without being conscious of it."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',7,NULL,'cloze','{"stem":"第 2 空","context":"True eccentrics disregard social conventions without ___1___ conscious of it. Dickie, a shrewd businessman, was caught in the rain and walked ___2___ an expensive store. A clerk refused to serve him, but Dickie paid no ___3___ and asked for the manager. He later paid for the watch with 30,000 pennies ___4___ all.","blank_no":2,"options":["into","at","of","off"],"answer_index":0,"explanation_cn":"“走进”某处用 walk into,表示向里移动。✓ walked into an expensive store."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',7,NULL,'cloze','{"stem":"第 3 空","context":"True eccentrics disregard social conventions without ___1___ conscious of it. Dickie, a shrewd businessman, was caught in the rain and walked ___2___ an expensive store. A clerk refused to serve him, but Dickie paid no ___3___ and asked for the manager. He later paid for the watch with 30,000 pennies ___4___ all.","blank_no":3,"options":["attention","care","mind","price"],"answer_index":0,"explanation_cn":"“理会、注意”用 pay attention。✓ Dickie paid no attention and asked for the manager."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',7,NULL,'cloze','{"stem":"第 4 空","context":"True eccentrics disregard social conventions without ___1___ conscious of it. Dickie, a shrewd businessman, was caught in the rain and walked ___2___ an expensive store. A clerk refused to serve him, but Dickie paid no ___3___ and asked for the manager. He later paid for the watch with 30,000 pennies ___4___ all.","blank_no":4,"options":["in","on","at","by"],"answer_index":0,"explanation_cn":"“总共”用 in all。✓ 30,000 pennies in all."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',8,NULL,'choice','{"stem":"Why did the clerk refuse to serve Dickie?","options":["He was rude to the clerk","He was a snob","He looked bedraggled after the rain","He had no money"],"answer_index":2,"explanation_cn":"课文说 he was in such a bedraggled condition that a clerk refused to serve him——他淋雨后一副狼狈相,店员才拒绝招待。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',8,NULL,'choice','{"stem":"How did Dickie pay for the $300 watch?","options":["With 30,000 pennies in a cloth bag","With a check","With a single gold coin","With a credit card"],"answer_index":0,"explanation_cn":"课文说 It contained $300 in pennies, thirty thousand pennies in all——他用装了三万枚硬币的布袋付账。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',8,NULL,'choice','{"stem":"Who had really painted the ''famous'' modern pictures?","options":["Famous artists","His wife","The critics","Dickie himself"],"answer_index":3,"explanation_cn":"课文说 the pictures…had in fact all been painted by Dickie himself——那些“名家”画作其实全是迪基自己画的。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',9,NULL,'choice','{"stem":"你想说\"他没理会那个店员\"(pay attention):","options":["He paid no attention the clerk.","He paid not attention to the clerk.","He paid no attention to the clerk.","He paid no attention on the clerk."],"answer_index":2,"explanation_cn":"“理会、注意某人”用 pay attention to sb,介词是 to。✓ He paid no attention to the clerk. 场合:说某人“没理会、不在意”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',9,NULL,'choice','{"stem":"你想说\"经理知道这位顾客是谁\"(间接疑问):","options":["The manager knew who the customer was.","The manager knew who the customer is he.","The manager knew was who the customer.","The manager knew who was the customer."],"answer_index":0,"explanation_cn":"间接疑问句用陈述句的正常语序,不倒装(不是 who was the customer)。✓ The manager knew who the customer was. 场合:把一个问句嵌进另一句话里。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',9,NULL,'choice','{"stem":"你想说\"他坚持要店员点清钱数\"(insist on + 物主代词 + 动名词):","options":["He insisted on the clerk count the money.","He insisted the clerk to count the money.","He insisted on the clerk to count the money.","He insisted on the clerk''s counting the money."],"answer_index":3,"explanation_cn":"insist on 后接动名词,做动作的人用物主形式(the clerk''s)。✓ He insisted on the clerk''s counting the money. 场合:坚持要某人做某事。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',10,NULL,'choice','{"stem":"eccentric 的意思是:","options":["勤奋的","礼貌的","普通的","(行为)古怪的"],"answer_index":3,"explanation_cn":"eccentric = (行为)古怪的。✓ true eccentrics."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',10,NULL,'choice','{"stem":"reprimand 的意思是:","options":["表扬","邀请","训斥,斥责","感谢"],"answer_index":2,"explanation_cn":"reprimand = 训斥、斥责。✓ reprimanded the clerk severely 狠狠训斥了店员。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',10,NULL,'choice','{"stem":"\"They disregard conventions without ___ conscious of it.\"(without 后接动名词)","options":["to be","being","be","been"],"answer_index":1,"stem_cn":"他们打破习俗却意识不到。","explanation_cn":"介词 without 后接动名词 -ing。✓ without being conscious of it. ✗ be / to be / been:介词后用动名词 being。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',10,NULL,'choice','{"stem":"\"Dickie paid no ___ to the clerk.\"(pay ___ to sb)","options":["price","care","attention","mind"],"answer_index":2,"stem_cn":"迪基没理会那个店员。","explanation_cn":"“理会、注意”用 pay attention to sb。✓ Dickie paid no attention to the clerk. ✗ care / mind / price:pay 搭配 attention。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',10,NULL,'choice','{"stem":"\"on foot\" 的意思是:","options":["步行","秘密地","立刻","大声地"],"answer_index":0,"explanation_cn":"on foot = 步行。✓ preferring always to go on foot 总爱步行。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',10,NULL,'choice','{"stem":"\"draw attention to oneself\" 的意思是:","options":["保持安静","独自离开","画一幅自画像","引起别人对自己的注意"],"answer_index":3,"explanation_cn":"draw attention to oneself = 引起别人对自己的注意。✓ never draw attention to themselves 从不引人注目。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',10,NULL,'choice','{"stem":"Why do people love true eccentrics, according to the passage?","options":["They add color to the dull routine of everyday life","They are very rich","They follow every social rule","They give away their money"],"answer_index":0,"passage":"True eccentrics never deliberately set out to draw attention to themselves. They disregard social conventions without being conscious that they are doing anything out of the ordinary. This invariably wins them the affection and respect of others, for they add color to the dull routine of everyday life. Up to the time of his death, Richard Colson was one of the most notable figures in our town. He was a shrewd and wealthy businessman, but most people hardly knew anything about that side of his life. To all of us he was simply Dickie, and his eccentricity had become legendary long before he died. Dickie disliked snobs intensely. Though he owned a large car, he hardly ever used it, preferring always to go on foot. Even when it was pouring, he refused to carry an umbrella. One day, after being caught in a heavy shower, he walked into an expensive store to buy a $300 watch for his wife. He was in such a bedraggled condition that a clerk refused to serve him. Dickie left without a word and came back carrying a large cloth bag. Since it was extremely heavy, he dumped it on the counter. The clerk asked him to leave, but Dickie paid no attention and asked to see the manager. Recognizing who the customer was, the manager was most apologetic and reprimanded the clerk severely. When Dickie was handed the watch, he presented the clerk with the cloth bag. It contained $300 in pennies, thirty thousand pennies in all! He insisted on the clerk''s counting every coin before he left. On another occasion, he invited a number of important critics to view his private collection of modern paintings. The exhibition received a great deal of attention in the press, for though the pictures were supposed to be the work of famous artists, they had in fact all been painted by Dickie himself. It had taken him four years to stage this elaborate joke, simply to prove that critics do not always know what they are talking about.","explanation_cn":"课文说 they add color to the dull routine of everyday life——怪人给平淡日子添了色彩,所以惹人喜爱。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',10,NULL,'choice','{"stem":"Why did Dickie forge the modern paintings?","options":["To help famous artists","To decorate his home","To prove critics don''t always know what they''re talking about","To sell them for money"],"answer_index":2,"passage":"True eccentrics never deliberately set out to draw attention to themselves. They disregard social conventions without being conscious that they are doing anything out of the ordinary. This invariably wins them the affection and respect of others, for they add color to the dull routine of everyday life. Up to the time of his death, Richard Colson was one of the most notable figures in our town. He was a shrewd and wealthy businessman, but most people hardly knew anything about that side of his life. To all of us he was simply Dickie, and his eccentricity had become legendary long before he died. Dickie disliked snobs intensely. Though he owned a large car, he hardly ever used it, preferring always to go on foot. Even when it was pouring, he refused to carry an umbrella. One day, after being caught in a heavy shower, he walked into an expensive store to buy a $300 watch for his wife. He was in such a bedraggled condition that a clerk refused to serve him. Dickie left without a word and came back carrying a large cloth bag. Since it was extremely heavy, he dumped it on the counter. The clerk asked him to leave, but Dickie paid no attention and asked to see the manager. Recognizing who the customer was, the manager was most apologetic and reprimanded the clerk severely. When Dickie was handed the watch, he presented the clerk with the cloth bag. It contained $300 in pennies, thirty thousand pennies in all! He insisted on the clerk''s counting every coin before he left. On another occasion, he invited a number of important critics to view his private collection of modern paintings. The exhibition received a great deal of attention in the press, for though the pictures were supposed to be the work of famous artists, they had in fact all been painted by Dickie himself. It had taken him four years to stage this elaborate joke, simply to prove that critics do not always know what they are talking about.","explanation_cn":"课文说 simply to prove that critics do not always know what they are talking about——他伪造画展只为证明评论家未必真懂。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',10,NULL,'choice','{"stem":"What did Dickie want to buy for his wife?","options":["A cloth bag","A $300 watch","A large car","A modern painting"],"answer_index":1,"audio":"True eccentrics never deliberately set out to draw attention to themselves. They disregard social conventions without being conscious that they are doing anything out of the ordinary. This invariably wins them the affection and respect of others, for they add color to the dull routine of everyday life. Up to the time of his death, Richard Colson was one of the most notable figures in our town. He was a shrewd and wealthy businessman, but most people hardly knew anything about that side of his life. To all of us he was simply Dickie, and his eccentricity had become legendary long before he died. Dickie disliked snobs intensely. Though he owned a large car, he hardly ever used it, preferring always to go on foot. Even when it was pouring, he refused to carry an umbrella. One day, after being caught in a heavy shower, he walked into an expensive store to buy a $300 watch for his wife. He was in such a bedraggled condition that a clerk refused to serve him. Dickie left without a word and came back carrying a large cloth bag. Since it was extremely heavy, he dumped it on the counter. The clerk asked him to leave, but Dickie paid no attention and asked to see the manager. Recognizing who the customer was, the manager was most apologetic and reprimanded the clerk severely. When Dickie was handed the watch, he presented the clerk with the cloth bag. It contained $300 in pennies, thirty thousand pennies in all! He insisted on the clerk''s counting every coin before he left. On another occasion, he invited a number of important critics to view his private collection of modern paintings. The exhibition received a great deal of attention in the press, for though the pictures were supposed to be the work of famous artists, they had in fact all been painted by Dickie himself. It had taken him four years to stage this elaborate joke, simply to prove that critics do not always know what they are talking about.","explanation_cn":"课文说 to buy a $300 watch for his wife——他想给妻子买一块三百美元的手表。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l31',10,NULL,'choice','{"stem":"How long did the elaborate painting joke take to stage?","options":["Four weeks","Four months","Four years","Four days"],"answer_index":2,"audio":"True eccentrics never deliberately set out to draw attention to themselves. They disregard social conventions without being conscious that they are doing anything out of the ordinary. This invariably wins them the affection and respect of others, for they add color to the dull routine of everyday life. Up to the time of his death, Richard Colson was one of the most notable figures in our town. He was a shrewd and wealthy businessman, but most people hardly knew anything about that side of his life. To all of us he was simply Dickie, and his eccentricity had become legendary long before he died. Dickie disliked snobs intensely. Though he owned a large car, he hardly ever used it, preferring always to go on foot. Even when it was pouring, he refused to carry an umbrella. One day, after being caught in a heavy shower, he walked into an expensive store to buy a $300 watch for his wife. He was in such a bedraggled condition that a clerk refused to serve him. Dickie left without a word and came back carrying a large cloth bag. Since it was extremely heavy, he dumped it on the counter. The clerk asked him to leave, but Dickie paid no attention and asked to see the manager. Recognizing who the customer was, the manager was most apologetic and reprimanded the clerk severely. When Dickie was handed the watch, he presented the clerk with the cloth bag. It contained $300 in pennies, thirty thousand pennies in all! He insisted on the clerk''s counting every coin before he left. On another occasion, he invited a number of important critics to view his private collection of modern paintings. The exhibition received a great deal of attention in the press, for though the pictures were supposed to be the work of famous artists, they had in fact all been painted by Dickie himself. It had taken him four years to stage this elaborate joke, simply to prove that critics do not always know what they are talking about.","explanation_cn":"课文说 It had taken him four years to stage this elaborate joke——他花了整整四年策划这个玩笑。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
